function futureValue(pv, pmt, annualRate, years, freq){
  var r=annualRate/freq; var n=years*freq;
  var fvPv = pv*Math.pow(1+r,n);
  var fvPmt = (r===0)? pmt*n : pmt*((Math.pow(1+r,n)-1)/r);
  return +(fvPv+fvPmt).toFixed(2);
}
function growthTable(pv,pmt,rate,years,freq){ var rows=[]; for(var y=1;y<=years;y++){ rows.push({year:y, fv:futureValue(pv,pmt,rate,y,freq)}); } return rows; }
var EXPORTS={futureValue:futureValue, growthTable:growthTable};


function rngFactory(seed){ var s=(seed>>>0)||1; return function(){ s=(s*1664525+1013904223)>>>0; return s/4294967296; }; }

if (typeof module !== 'undefined' && module.exports) { module.exports = EXPORTS; }
if (typeof window !== 'undefined') { window.InvestmentForgePure = EXPORTS; }
